### Eligibility Engine
```java
@Service
public class EligibilityEngine {

  public EligibilityAssessment assess(
      EligibilityRule rule,
      Counterparty buyer) {

    if (!buyer.entityType().equals(rule.allowedEntityType())) {
      return EligibilityAssessment.blocked("Ineligible entity type");
    }
    if (buyer.jurisdiction().equals(rule.restrictedJurisdiction())) {
      return EligibilityAssessment.blocked("Restricted jurisdiction");
    }
    return EligibilityAssessment.ok();
  }
}
