@Service
public class EsgObligationScheduler {

  @Scheduled(cron = "0 0 1 * * *")
  public void evaluateDueDates() {

    LocalDate today = LocalDate.now();

    for (EsgObligation o : repo.findActive()) {

      if (today.isAfter(o.getDueDate())) {
        o.setStatus("OVERDUE");
        repo.save(o);

        audit.log(
          "ESG_OBLIGATION_OVERDUE",
          o.getLoanId(),
          o.getObligationCode()
        );
      }
    }
  }
}
