@Service
public class EsgValidationService {

  public void validate(UUID submissionId) {

    EsgSubmission s = repo.find(submissionId);

    if (s.getReportedValue().signum() < 0)
      reject(s, "NEGATIVE_VALUE");

    if (s.getPeriodEnd().isAfter(LocalDate.now()))
      reject(s, "FUTURE_PERIOD");

    s.setStatus("VALIDATED");
    repo.save(s);

    audit.log("ESG_VALIDATED", submissionId);
