public record LoanDiff(List<DiffItem> changes) {
  public record DiffItem(String field, String fromValue, String toValue) {}

  public static LoanDiff compare(CanonicalLoan a, CanonicalLoan b) {
    List<DiffItem> out = new ArrayList<>();
    if (a.economics().marginBps() != b.economics().marginBps()) {
      out.add(new DiffItem("economics.marginBps",
        String.valueOf(a.economics().marginBps()),
        String.valueOf(b.economics().marginBps())));
    }
    if (!a.dates().maturityDate().equals(b.dates().maturityDate())) {
      out.add(new DiffItem("dates.maturityDate",
        a.dates().maturityDate().toString(),
        b.dates().maturityDate().toString()));
    }
    return new LoanDiff(out);
  }
}
