@Component
public class SchemaValidator {
  private final JsonSchema schema;
  private final ObjectMapper mapper = new ObjectMapper();

  public SchemaValidator(@Value("${canon.schemaPath}") String schemaPath) throws Exception {
    JsonSchemaFactory factory = JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V202012);
    JsonNode node = mapper.readTree(new File(schemaPath));
    this.schema = factory.getSchema(node);
  }

  public void validate(String json) {
    try {
      Set<ValidationMessage> errors = schema.validate(mapper.readTree(json));
      if (!errors.isEmpty()) {
        throw new IllegalArgumentException("Schema validation failed: " + errors);
      }
    } catch (IOException e) {
      throw new RuntimeException(e);
    }
  }
}
